const section8 = "<0!49 1>"  // Hit · 1 bars · 145 BPM · E · Em C D B

// ========== drums ==========
// Crescendo · bars 1-9 · pattern C
// Drums · RolandTR909
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.9).distort(2.8).distortvol(.5).crush(10).mask(section1).velocity(section1).orbit(1).analyze("kick")
$: s("~ [cp ~ ~ ~] ~ [cp ~ ~ cp]").bank("RolandTR909").gain(0.72).distort(2.8).distortvol(.5).crush(10).mask(section1).velocity(section1).orbit(1).analyze("snare")
$: s("[hh ~ hh hh] [~ hh ~ hh] [hh ~ hh hh] [~ hh ~ hh]").bank("RolandTR909").gain(0.45).distort(2.8).distortvol(.5).crush(10).mask(section1).velocity(section1).orbit(1).analyze("hats")
$: s("[~ ~ oh ~] [~ ~ oh ~] [~ ~ oh ~] [~ ~ oh ~]").bank("RolandTR909").gain(0.41).distort(2.8).distortvol(.5).crush(10).mask(section1).velocity(section1).orbit(1).analyze("hats")
$: s("[~ ~ rd ~] [~ ~ rd ~] [~ ~ rd ~] [~ ~ rd ~]").bank("RolandTR909").gain(0.32).distort(2.8).distortvol(.5).crush(10).mask(section1).velocity(section1).orbit(1).analyze("hats")
// Crescendo 2 · bars 10-33 · pattern C
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR909").gain(0.9).distort(2.8).distortvol(.5).crush(10).mask(section2).velocity(section2).orbit(1).analyze("kick")
