// ========== bass ==========
// Crescendo · bars 1-9 · pattern A
// Bass · Rumble
$: note("<a1>").transpose(-5).struct("[~ x x] [~ x x] [~ x x] [~ x x]")
  .s("sawtooth").lpf(500).lpq(10).distort(4).distortvol(.5)
  .decay(.1).sustain(0).gain(0.6).mask(section1).velocity(section1).orbit(2).analyze("bass")
// Crescendo 2 · bars 10-33 · pattern A
$: note("<e1 a1 f1 g1>").transpose(-5).struct("[~ x x] [~ x x] [~ x x] [~ x x]")
  .s("sawtooth").lpf(500).lpq(10).distort(4).distortvol(.5)
  .decay(.1).sustain(0).gain(0.6).mask(section2).velocity(section2).orbit(2).analyze("bass")
// Build · bars 36-38 · pattern A
$: note("<f1 g1 e1 a1>").transpose(-5).struct("[~ x x] [~ x x] [~ x x] [~ x x]")
  .s("sawtooth").lpf("<350 500 200>").lpq(10).distort(3).distortvol(.5)
  .decay(.1).sustain(0).gain("<0.53 0.6 0.45>").mask("<1 [1 0] 1>").mask(section4).velocity(section4).orbit(2).analyze("bass")
// Drop · bars 39-46 · pattern A
$: note("<g1 e1 a1 f1>").transpose(-5).struct("[~ x x] [~ x x] [~ x x] [~ x x]")
  .s("sawtooth").lpf(500).lpq(10).distort(4).distortvol(.5)
  .decay(.1).sustain(0).gain(0.6).mask(section5).velocity(section5).orbit(2).analyze("bass")
// Final · bars 49-49 · pattern A
