  .decay(.1).sustain(0).gain(0.6).mask(section7).velocity(section7).orbit(2).analyze("bass")
// Hit · bars 50-50 · pattern B
// Bass · Long sub
$: note("<e1 a1 f1 g1>").transpose(-5).struct("x")
  .s("sine").lpf(300).lpq(2).distort(1).distortvol(.5)
  .decay(.6).sustain(.8).gain(0.8).mask(section8).velocity(section8).orbit(2).analyze("bass")

// ========== arp ==========
// Crescendo · bars 1-9 · pattern A
// Arpeggio · Acid, 8ths
$: note("<[a3 a3 [a4 a3] c4 a3 e4 [a3 a4] c4]>").transpose(-5)
  .s("sawtooth").lpf("<1600 1962.5 2325 2687.5 3050 3412.5 3775 4137.5 4500>").lpq(24).distort(2).distortvol(.5)
  .decay(.15).sustain(.15).gain(0.34).degradeBy(0.5).mask(section1).velocity(section1).orbit(3).analyze("arp")
// Crescendo 2 · bars 10-33 · pattern A
$: note("<[g#3 g#3 [g#4 g#3] b3 g#3 e4 [g#3 g#4] b3] [a3 a3 [a4 a3] c4 a3 e4 [a3 a4] c4] [f3 f3 [f4 f3] a3 f3 c4 [f3 f4] a3] [g3 g3 [g4 g3] b3 g3 d4 [g3 g4] b3]>").transpose(-5)
