  .decay(.15).sustain(.15).gain(0.34).degradeBy(0.5).mask(section2).velocity(section2).orbit(3).analyze("arp")
// Glitch · bars 34-35 · pattern A
$: note("<[g#3 g#3 [g#4 g#3] b3 g#3 e4 [g#3 g#4] b3] [a3 a3 [a4 a3] c4 a3 e4 [a3 a4] c4] [f3 f3 [f4 f3] a3 f3 c4 [f3 f4] a3] [g3 g3 [g4 g3] b3 g3 d4 [g3 g4] b3]>").transpose(-5)
  .s("sawtooth").lpf("<900 300>").lpq(22).distort(1.5).distortvol(.5)
  .decay(.15).sustain(.15).gain(0.3).degradeBy(0.5).mask(section3).velocity(section3).orbit(3).analyze("arp")
// Build · bars 36-38 · pattern A
$: note("<[f3 f3 [f4 f3] a3 f3 c4 [f3 f4] a3] [g3 g3 [g4 g3] b3 g3 d4 [g3 g4] b3] [g#3 g#3 [g#4 g#3] b3 g#3 e4 [g#3 g#4] b3] [a3 a3 [a4 a3] c4 a3 e4 [a3 a4] c4]>").transpose(-5)
