  .s("sawtooth").lpf("<2428.57 2842.86 3257.14 3671.43 4085.71 4500 1600 2014.29>").lpq(24).distort(2).distortvol(.5)
  .decay(.15).sustain(.15).gain(0.34).degradeBy(0.5).mask(section5).velocity(section5).orbit(3).analyze("arp")
// Glitch break · bars 47-48 · pattern A
$: note("<[g3 g3 [g4 g3] b3 g3 d4 [g3 g4] b3] [g#3 g#3 [g#4 g#3] b3 g#3 e4 [g#3 g#4] b3] [a3 a3 [a4 a3] c4 a3 e4 [a3 a4] c4] [f3 f3 [f4 f3] a3 f3 c4 [f3 f4] a3]>").transpose(-5)
