  .s("square").fm(5).vowel("<a e i o>").lpf(3500).crush(8)
  .decay(.2).sustain(.3).delay(.45).room(.3).gain(0.22).mask(section1).velocity(section1).orbit(4).analyze("hook")
// Crescendo 2 · bars 10-33 · pattern A
$: n("<[0 ~ 3 ~ 8 7 ~ ~] [0 ~ 3 ~ 7 ~ 3 1]>").scale("E4:phrygian")
