  .decay(.2).sustain(.3).delay(.45).room(.3).gain(0.22).mask(section5).velocity(section5).orbit(4).analyze("hook")
// Final · bars 49-49 · pattern A
$: n("<[0 ~ 3 ~ 7 ~ 3 1] [0 ~ 3 ~ 8 7 ~ ~]>").scale("E4:phrygian")
  .s("square").fm(5).vowel("<a e i o>").lpf(3500).crush(8)
  .decay(.2).sustain(.3).delay(.45).room(.3).gain(0.22).mask(section7).velocity(section7).orbit(4).analyze("hook")

// ========== pad ==========
// Crescendo · bars 1-9 · pattern A
// Pad · Stab
$: note("<[a2,c3,e3]>").transpose(-5).struct("x ~ ~ x ~ ~ x ~ ~ ~ x ~ x ~ ~ ~")
  .s("supersaw").attack(.01).decay(.15).sustain(0).release(.1).lpf(3200).distort(1.5).distortvol(.5)
  .room(.3).gain(0.3).mask(section1).velocity(section1).orbit(6).analyze("pad")
// Crescendo 2 · bars 10-33 · pattern A
$: note("<[g#2,b2,e3] [a2,c3,e3] [f2,a2,c3] [g2,b2,d3]>").transpose(-5).struct("x ~ ~ x ~ ~ x ~ ~ ~ x ~ x ~ ~ ~")
