  .room(.3).gain(0.3).mask(section2).velocity(section2).orbit(6).analyze("pad")
// Drop · bars 39-46 · pattern A
$: note("<[g2,b2,d3] [g#2,b2,e3] [a2,c3,e3] [f2,a2,c3]>").transpose(-5).struct("x ~ ~ x ~ ~ x ~ ~ ~ x ~ x ~ ~ ~")
